\set ON_ERROR_STOP on
create function public.test_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
select test_assert((select bool_and(published_to_class) from rizsim_course_materials),'Existing library publication preserved');
select test_assert((select count(*) from pg_tables where schemaname='public' and tablename in ('rizsim_course_catalogue','rizsim_purchased_course_licenses','rizsim_course_resource_publications','rizsim_session_resources') and rowsecurity)=4,'All new tables have RLS');
select test_assert(not has_function_privilege('anon','public.create_rizsim_runtime_resource(text,uuid,uuid,jsonb)','execute'),'Anonymous resource writes denied');
select test_assert(not has_table_privilege('authenticated','public.rizsim_course_catalogue','insert'),'Faculty cannot publish catalogue');
select test_assert(not has_table_privilege('authenticated','public.rizsim_purchased_course_licenses','insert'),'Faculty cannot grant purchased access');
set role authenticated;set request.jwt.claim.sub='10000000-0000-4000-8000-000000000001';
select test_assert((get_rizsim_course_runtime('20000000-0000-4000-8000-000000000001','own')->>'can_add')::boolean,'Course Lead owns writable environment');
select set_rizsim_resource_publication('own','20000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001',false);
set request.jwt.claim.sub='10000000-0000-4000-8000-000000000004';
select test_assert(not rizsim_runtime_student_material('60000000-0000-4000-8000-000000000001'),'Revocation removes learner access');
set request.jwt.claim.sub='10000000-0000-4000-8000-000000000001';
select set_rizsim_resource_publication('own','20000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001',true);
set request.jwt.claim.sub='10000000-0000-4000-8000-000000000004';
select test_assert(rizsim_runtime_student_material('60000000-0000-4000-8000-000000000001'),'Publishing restores eligible learner access');
set request.jwt.claim.sub='10000000-0000-4000-8000-000000000002';
do $$begin perform get_rizsim_course_runtime('20000000-0000-4000-8000-000000000001','own');raise exception 'TEST_UNEXPECTED_SUCCESS';exception when others then if sqlerrm='TEST_UNEXPECTED_SUCCESS' then raise;end if;raise notice 'PASS: ordinary Faculty cannot open owned course';end$$;
select test_assert(rizsim_runtime_manage_session('50000000-0000-4000-8000-000000000002'),'Faculty can manage own standalone resources');
select test_assert(not rizsim_runtime_manage_session('50000000-0000-4000-8000-000000000001'),'Faculty cannot manage another account session');
select create_rizsim_runtime_resource('simulation','50000000-0000-4000-8000-000000000002','70000000-0000-4000-8000-000000000001','{"title":"Session link","description":"Test","material_type":"reading","source_type":"link","external_url":"https://example.org/session"}');
select create_rizsim_runtime_resource('simulation','50000000-0000-4000-8000-000000000002','70000000-0000-4000-8000-000000000001','{"title":"Session link","description":"Test","material_type":"reading","source_type":"link","external_url":"https://example.org/session"}');
select test_assert((select count(*) from rizsim_session_resources)=1,'Resource retries are idempotent');
do $$begin perform create_rizsim_runtime_resource('simulation','50000000-0000-4000-8000-000000000002',gen_random_uuid(),'{"title":"Unsafe","material_type":"reading","source_type":"link","external_url":"javascript:alert(1)"}');raise exception 'TEST_UNEXPECTED_SUCCESS';exception when others then if sqlerrm='TEST_UNEXPECTED_SUCCESS' then raise;end if;raise notice 'PASS: unsafe links rejected server-side';end$$;
insert into storage.objects(bucket_id,name) values('course-materials','sessions/50000000-0000-4000-8000-000000000002/70000000-0000-4000-8000-000000000002-file.pdf');
select test_assert(rizsim_runtime_session_path('sessions/50000000-0000-4000-8000-000000000002/70000000-0000-4000-8000-000000000002-file.pdf'),'Upload confined to owned standalone path');
select test_assert(not rizsim_runtime_session_path('20000000-0000-4000-8000-000000000001/file.pdf'),'Ordinary Faculty never gains course storage write');
select create_rizsim_runtime_resource('simulation','50000000-0000-4000-8000-000000000002','70000000-0000-4000-8000-000000000002','{"title":"File","material_type":"reading","source_type":"file","storage_path":"sessions/50000000-0000-4000-8000-000000000002/70000000-0000-4000-8000-000000000002-file.pdf","file_name":"file.pdf","mime_type":"application/pdf","file_size":20}');
set request.jwt.claim.sub='10000000-0000-4000-8000-000000000004';
select test_assert((select count(*) from get_my_rizsim_student_course_materials())=3,'Existing student read API includes only published eligible resources');
select test_assert((select count(*) from get_rizsim_course_material_view_context('70000000-0000-4000-8000-000000000002'))=1,'Protected session file has authorized viewer context');
reset role;
insert into rizsim_course_catalogue values('20000000-0000-4000-8000-000000000002',true,now());
insert into rizsim_purchased_course_licenses(id,course_id,user_id,starts_at,expires_at) values('80000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002',now()-interval '1 hour',now()+interval '1 day');
set role authenticated;set request.jwt.claim.sub='10000000-0000-4000-8000-000000000002';
select test_assert(jsonb_array_length(get_my_rizsim_purchased_courses())=1,'Only assigned purchased course listed');
select test_assert((get_rizsim_course_runtime('20000000-0000-4000-8000-000000000002','purchased')->>'can_add')::boolean=false,'Purchased environment is read-only');
do $$begin perform create_rizsim_runtime_resource('purchased','20000000-0000-4000-8000-000000000002',gen_random_uuid(),'{"title":"Bad","material_type":"reading","source_type":"link","external_url":"https://example.org"}');raise exception 'TEST_UNEXPECTED_SUCCESS';exception when others then if sqlerrm='TEST_UNEXPECTED_SUCCESS' then raise;end if;raise notice 'PASS: purchaser cannot add or edit publisher content';end$$;
select set_rizsim_resource_publication('purchased','20000000-0000-4000-8000-000000000002','60000000-0000-4000-8000-000000000002',true);
select test_assert((get_rizsim_course_runtime('20000000-0000-4000-8000-000000000002','purchased')->'resources'->0->>'published_to_class')::boolean,'Purchaser publication stored separately');
select create_rizsim_purchased_course_session('20000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000001','Purchased session','practice',null,null,now(),now()+interval '1 hour');
do $$begin perform create_rizsim_purchased_course_session('20000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000002','Not included','practice',null,null,now(),now()+interval '1 hour');raise exception 'TEST_UNEXPECTED_SUCCESS';exception when others then if sqlerrm='TEST_UNEXPECTED_SUCCESS' then raise;end if;raise notice 'PASS: purchased session rejects an unincluded simulation';end$$;
set request.jwt.claim.sub='10000000-0000-4000-8000-000000000003';
select test_assert(jsonb_array_length(get_my_rizsim_purchased_courses())=0,'Other Faculty cannot see another purchase');
reset role;
select test_assert((select title from rizsim_course_materials where id='60000000-0000-4000-8000-000000000002')='Publisher reading','Publisher resource content unchanged');
update rizsim_purchased_course_licenses set revoked_at=now() where id='80000000-0000-4000-8000-000000000001';
select test_assert(not exists(select 1 from classroom_sessions where purchased_course_license_id='80000000-0000-4000-8000-000000000001' and active),'Revoked purchase closes only its sessions');
select test_assert((select active from classroom_sessions where id='50000000-0000-4000-8000-000000000002'),'Unrelated standalone session unchanged');
select test_assert((select count(*) from rizsim_course_materials)=2,'Publish and revoke never delete library resources');
